    end
  end

  on_linux do
    on_arm do
      url "https://github.com/matteopolak/jacket/releases/download/v0.35.1/jacket-linux-arm64.tar.gz"
      sha256 "0d81c6c92a7a6a3ab49a4addc1384a7cf5240cca6399a7a1209fdb3753211f3a"
    end
    on_intel do
