      sha256 "cd34f6b055a7655b6d4df44f4628680acadd3a49a583a626566564d19e54238d"
    end
  end

  def install
    # jacket starts the other tools from beside the real file behind its bin/ symlink.
    # jaic, jailint and jailsp find stdlib/ (including its prelude) next to the real file
    # behind the bin/ symlinks, and native libraries (wgpu-native, stb_*, rpmalloc) in
    # ../native-libs. jaic opens its code generation library (libjaic_backend) from beside the
    # real file too, on the first build that writes native code.
    libexec.install "jacket", "jaic", "jailsp", "jailint", "jaifmt", "stdlib"
    libexec.install Dir["libjaic_backend.*"]
    libexec.install "native-libs"
    bin.install_symlink libexec/"jacket", libexec/"jaic", libexec/"jailsp", libexec/"jailint", libexec/"jaifmt"
    doc.install "README.md", "CHANGELOG.md"
  end

  test do
    (testpath/"hello.jai").write <<~JAI
      #import "Basic";

      main :: () {
          print("Hello from Homebrew!\\n");
      }
    JAI
    assert_equal "Hello from Homebrew!\n", shell_output("#{bin}/jaic hello.jai -interp")
    assert_equal "main :: () {\n    x := 1;\n}\n", pipe_output("#{bin}/jaifmt --stdin", "main::(){x:=1;}")
    system bin/"jailint", "hello.jai"
    assert_match "jacket", shell_output("#{bin}/jacket version")
  end
end
